"""Gabarits HTML (Jinja) de l'application de pointage."""

# Logo GCA intégré (PNG en base64) : aucun dossier static nécessaire.
LOGO_B64 = ""

BASE = r"""<!DOCTYPE html>
<html lang="fr">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>{% block title %}GCA{% endblock %}</title>
<link rel="icon" type="image/png" href="/logo.png">
<style>
:root{--bg:#f6f7f9;--card:#fff;--tx:#1b1f24;--mu:#6b7380;--bd:#e2e5ea;--ac:#1f6feb;--ok:#1a8f4c;--ko:#c93c37}
@media (prefers-color-scheme:dark){:root{--bg:#14171b;--card:#1d2228;--tx:#e8eaed;--mu:#9aa3af;--bd:#2c333b;--ac:#58a6ff;--ok:#3fb868;--ko:#f0716b}}
*{box-sizing:border-box}
body{margin:0;background:var(--bg);color:var(--tx);font:15px/1.5 system-ui,-apple-system,"Segoe UI",Roboto,sans-serif}
main{max-width:960px;margin:0 auto;padding:16px}
h1{font-size:20px;margin:0}h2{font-size:16px;margin:0 0 10px}
header{display:flex;justify-content:space-between;align-items:center;gap:8px;margin-bottom:14px;flex-wrap:wrap}
nav{display:flex;gap:6px;flex-wrap:wrap;align-items:center}
nav a,nav button{border:1px solid var(--bd);background:var(--card);color:var(--tx);padding:7px 14px;border-radius:99px;text-decoration:none;font:inherit;cursor:pointer}
nav a.on{background:var(--ac);border-color:var(--ac);color:#fff}
.card{background:var(--card);border:1px solid var(--bd);border-radius:12px;padding:16px;margin-bottom:14px}
.row{display:flex;gap:10px;flex-wrap:wrap;align-items:end}
label{display:flex;flex-direction:column;font-size:12px;color:var(--mu);gap:3px}
input,select,button{font:inherit;color:var(--tx)}
input,select{background:var(--card);border:1px solid var(--bd);border-radius:8px;padding:8px 10px;max-width:100%}
.b{background:var(--ac);color:#fff;border:0;padding:9px 16px;border-radius:8px;cursor:pointer;text-decoration:none;display:inline-block}
.g{background:transparent;border:1px solid var(--bd);padding:8px 14px;border-radius:8px;cursor:pointer;color:var(--tx);text-decoration:none;display:inline-block}
.x{background:none;border:0;color:var(--ko);cursor:pointer;padding:0 4px}
.sc{overflow-x:auto}
table{border-collapse:collapse;width:100%;min-width:520px}
th,td{text-align:left;padding:7px 8px;border-bottom:1px solid var(--bd);white-space:nowrap}
th{font-size:12px;color:var(--mu);font-weight:600}
.mu{color:var(--mu)}.err{color:var(--ko);font-weight:600}.okc{color:var(--ok);font-weight:600}
form.inline{display:inline}
table.wrap td,table.wrap th{white-space:normal}
.chip{display:inline-block;border:1px solid var(--bd);border-radius:99px;padding:2px 6px 2px 12px;margin:3px 6px 3px 0}
.stat{border:1px solid var(--bd);border-radius:10px;padding:8px 14px;min-width:120px}.stat b{display:block;font-size:20px}.stat span{font-size:12px;color:var(--mu)}
</style>
</head>
<body><main>{% block body %}{% endblock %}</main><script>
document.addEventListener("input",function(ev){var i=ev.target;if(!i.classList||!i.classList.contains("tsearch"))return;
var norm=function(t){return t.toLowerCase().normalize("NFD").replace(/[\u0300-\u036f]/g,"")};
var q=norm(i.value.trim()),tb=i.closest(".card").querySelector("table"),n=0;
tb.querySelectorAll("tr").forEach(function(r,k){if(k===0||r.querySelector("th"))return;if(r.children.length===1&&r.children[0].colSpan>1)return;
var ok=!q||norm(r.textContent).indexOf(q)>-1;r.style.display=ok?"":"none";if(ok)n++});
var c=i.parentNode.querySelector(".tcount");if(c)c.textContent=q?(n+" résultat(s)"):""});
</script>
</body></html>"""

KIOSK = r"""{% extends "base.html" %}
{% block title %}GCA – Pointage{% endblock %}
{% block body %}
<div class="card" style="text-align:center;max-width:460px;margin:24px auto">
  <img src="/logo.png" alt="GCA" style="height:80px;width:auto"><h1 style="margin-top:6px">Pointage</h1>
  <div id="clk" style="font-size:44px;font-weight:700;font-variant-numeric:tabular-nums;margin-top:8px">--:--:--</div>
  <div id="dte" class="mu"></div>
  <form id="f" autocomplete="off" style="margin-top:18px;text-align:left">
    <label>Code salarié
      <input id="code" name="code" placeholder="Ex. LRH001" autocomplete="off" autocapitalize="characters"
             autocorrect="off" spellcheck="false" inputmode="text"
             style="font-size:24px;text-align:center;letter-spacing:2px;text-transform:uppercase" autofocus>
    </label>
    <button id="ok" class="b" type="submit" style="width:100%;margin-top:14px;padding:20px;font-size:22px;font-weight:600;border-radius:14px;background:var(--ok)">OK</button>
  </form>
  <div id="res" style="margin-top:14px;font-size:17px;min-height:26px"></div>
  <p class="mu" style="font-size:13px;margin:10px 0 0">Saisissez votre code puis appuyez sur OK. L'arrivée ou le départ est détecté automatiquement.</p>
  <p style="margin:14px 0 0"><a class="mu" style="font-size:13px" href="/manager/login?new=1">Espace gérant</a></p>
</div>
<script>
const clk=document.getElementById("clk"),dte=document.getElementById("dte"),res=document.getElementById("res"),code=document.getElementById("code"),ok=document.getElementById("ok");
function tick(){const d=new Date();clk.textContent=d.toLocaleTimeString("fr-FR");dte.textContent=d.toLocaleDateString("fr-FR",{weekday:"long",day:"numeric",month:"long",year:"numeric"})}
tick();setInterval(tick,1000);
let timer;
document.getElementById("f").addEventListener("submit",async e=>{
  e.preventDefault();
  const v=code.value.trim();
  if(!v){show("Saisissez votre code salarié.",false);return}
  ok.disabled=true;
  try{
    const r=await fetch("/api/punch",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({code:v})});
    const j=await r.json();
    if(j.ok){showOk(j);code.value=""}else show(j.error||"Erreur.",false);
  }catch(err){show("Connexion impossible. Réessayez.",false)}
  ok.disabled=false;code.focus();
});
function showOk(j){res.textContent="";res.className="okc";const a=document.createElement("div");a.style.cssText="font-size:26px;font-weight:700";a.textContent="✓ "+j.name;const b=document.createElement("div");b.textContent=j.label+" à "+j.time;res.append(a,b);if(j.note){const n=document.createElement("div");n.style.cssText="margin-top:8px;font-size:20px;font-weight:600";n.textContent=j.note;res.append(n)}clearTimeout(timer);timer=setTimeout(()=>{res.textContent=""},8000)}
function show(t,good){res.textContent=t;res.className=good?"okc":"err";clearTimeout(timer);timer=setTimeout(()=>{res.textContent=""},8000)}
</script>
{% endblock %}"""

LOGIN = r"""{% extends "base.html" %}
{% block title %}GCA – Connexion gérant{% endblock %}
{% block body %}
<div class="card" style="max-width:380px;margin:40px auto">
  <img src="/logo.png" alt="GCA" style="height:64px;width:auto"><h1 style="margin-top:6px">Espace gérant</h1>
  <form method="post" style="margin-top:14px">
    <label>Mot de passe<input type="password" name="password" autofocus required></label>
    {% if error %}<p class="err">{{ error }}</p>{% endif %}
    <button class="b" type="submit" style="margin-top:12px;width:100%">Se connecter</button>
  </form>
  <p style="margin:14px 0 0"><a class="mu" style="font-size:13px" href="/">← Page de pointage</a></p>
</div>
{% endblock %}"""

NAV = r"""<header><div style="display:flex;align-items:center;gap:12px"><img src="/logo.png" alt="GCA" style="height:48px;width:auto"><h1>Espace gérant</h1></div>
<nav>
  <a href="{{ url_for('dashboard') }}" class="{{ 'on' if active=='dash' }}">Pointages & exports</a>
  <a href="{{ url_for('employees') }}" class="{{ 'on' if active=='emps' }}">Salariés</a>
  <a href="{{ url_for('kiosk') }}">Page de pointage</a>
  <form class="inline" method="post" action="{{ url_for('logout') }}"><button type="submit">Déconnexion</button></form>
</nav></header>"""

DASHBOARD = r"""{% extends "base.html" %}
{% block title %}GCA – Pointages{% endblock %}
{% block body %}
{% set active='dash' %}""" + NAV + r"""
<div class="card"><h2>Présents en ce moment ({{ present|length }}){% if site %} – {{ 'Sans site' if site == '__none__' else site }}{% endif %}</h2>
  {% if present %}<div>{% for p in present %}<span style="display:inline-block;margin:2px 10px 2px 0"><span style="color:var(--ok)">●</span> {{ p.name }} <span class="mu">depuis {{ p.ts|hm }}</span></span>{% endfor %}</div>
  {% else %}<span class="mu">Personne.</span>{% endif %}
</div>
<div class="card"><details><summary style="cursor:pointer;font-size:1.17em;font-weight:700">Pas encore pointés aujourd'hui ({{ not_punched|length }}){% if site %} – {{ 'Sans site' if site == '__none__' else site }}{% endif %} <span class="mu" style="font-size:13px;font-weight:400">▾ cliquer pour afficher / masquer</span></summary>
  <div style="margin-top:10px"></div>
  {% if not_punched %}<div>{% for p in not_punched %}<span style="display:inline-block;margin:2px 10px 2px 0"><span style="color:#d9534f">●</span> {{ p.name }}{% if p.horaire %} <span class="mu">({{ p.horaire }})</span>{% endif %}</span>{% endfor %}</div>
  <p class="mu" style="font-size:13px;margin:8px 0 0">Salariés actifs qui pointent ici, sans aucun pointage aujourd'hui et sans absence saisie (les salariés des sites sans pointage ne sont pas listés).</p>
  {% else %}<span class="mu">Tout le monde a pointé ou est déclaré absent.</span>{% endif %}
</details></div>
<div class="card"><details><summary style="cursor:pointer;font-size:1.17em;font-weight:700">Absents aujourd'hui ({{ absents|length }}){% if site %} – {{ 'Sans site' if site == '__none__' else site }}{% endif %} <span class="mu" style="font-size:13px;font-weight:400">▾ cliquer pour afficher / masquer</span></summary>
  <div style="margin-top:10px"></div>
  {% if absents %}<div>{% for p in absents %}<span style="display:inline-block;margin:2px 10px 2px 0"><span style="color:#888">●</span> {{ p.name }}{% if p.horaire %} <span class="mu">({{ p.horaire }})</span>{% endif %} <span class="mu">– {{ p.absence }}</span></span>{% endfor %}</div>
  <p class="mu" style="font-size:13px;margin:8px 0 0">Salariés avec une absence saisie pour aujourd'hui (congé, arrêt, formation, etc.), tous sites confondus.</p>
  {% else %}<span class="mu">Aucune absence saisie aujourd'hui.</span>{% endif %}
</details></div>
<div class="card"><details><summary style="cursor:pointer;font-size:1.17em;font-weight:700">Anomalies de pointage ({{ anom|length }}) <span class="mu" style="font-size:13px;font-weight:400">▾ oublis et incohérences sur la période choisie</span></summary>
  <div style="margin-top:10px"></div>
  {% if anom %}<div class="sc"><table>
    <tr><th>Salarié</th><th>Date</th><th>Anomalie</th><th>Détail</th></tr>
    {% for a in anom %}<tr><td><a href="{{ url_for('employee_page', eid=a.eid) }}">{{ a.name }}</a>{% if a.horaire %} <span class="mu">({{ a.horaire }})</span>{% endif %}</td><td>{{ a.day|day_fr }}</td><td><b>{{ a.kind }}</b></td><td>{{ a.detail }}</td></tr>{% endfor %}
  </table></div>
  <p class="mu" style="font-size:13px;margin:8px 0 0">Départ ou arrivée oubliés, jour ouvré (lundi-vendredi) sans pointage ni absence saisie, durée de plus de 12 h ou de moins de 10 min. Corrigez avec « Ajouter / corriger un pointage manuellement » ou saisissez l'absence : un passage saisi ou corrigé à la main n'est plus signalé. Mêmes données dans la feuille « Anomalies » de l'Excel.</p>
  {% else %}<span class="mu">Aucune anomalie sur la période.</span>{% endif %}
</details></div>
<div class="card"><h2>Ajouter / corriger un pointage manuellement</h2>
  <form method="post" action="{{ url_for('punch_add') }}" class="row">
    <input type="hidden" name="csrf_token" value="{{ csrf_token() }}">
    <label>Salarié<select name="emp" required>{% for e in emps if e.active %}<option value="{{ e.id }}">{{ e.name }}{{ e.code|cdp }}</option>{% endfor %}</select></label>
    <label>Date<input type="date" name="date" value="{{ today }}" required></label>
    <label>Heure<input type="time" name="time" required></label>
    <label>Type<select name="type"><option value="in">Arrivée</option><option value="out">Départ</option></select></label>
    <button class="b" type="submit">Ajouter</button>
  </form>
  <p class="mu" style="font-size:13px;margin:8px 0 0">Utile pour un départ oublié. Les heures saisies sont celles du fuseau Europe/Paris.</p>
</div>
<div class="card">
  <form method="get" class="row">
    <label>Site<select name="site" onchange="this.form.elements.emp.value='';if(this.form.elements.sub)this.form.elements.sub.value='';this.form.submit()"><option value="">Tous les sites</option>
      {% for n in site_names %}<option value="{{ n }}" {{ 'selected' if n|lower == site|lower }}>{{ n }}</option>{% endfor %}
      <option value="__none__" {{ 'selected' if site == '__none__' }}>Sans site</option></select></label>
    {% if uses_sub %}<label>Bâtiment<select name="sub" onchange="this.form.elements.emp.value='';this.form.submit()"><option value="">Tous les bâtiments</option>
      {% for n in sub_names %}<option value="{{ n }}" {{ 'selected' if n|lower == sub|lower }}>{{ n }}</option>{% endfor %}
      <option value="__none__" {{ 'selected' if sub == '__none__' }}>Sans bâtiment</option></select></label>{% endif %}
    <label>Du<input type="date" name="from" value="{{ d_from }}"></label>
    <label>Au<input type="date" name="to" value="{{ d_to }}"></label>
    <label>Salarié<select name="emp"><option value="">Tous</option>
      {% for e in emps %}<option value="{{ e.id }}" {{ 'selected' if e.id==emp_id }}>{{ e.name }}{{ e.code|cdp }}</option>{% endfor %}</select></label>
    <button class="b" type="submit">Filtrer</button>
    <a class="g" href="{{ url_for('export', kind='detail') }}?from={{ d_from }}&to={{ d_to }}&emp={{ emp_id or '' }}&site={{ site|urlencode }}&sub={{ sub|urlencode }}">⬇ Export détail (CSV)</a>
    <a class="g" href="{{ url_for('export', kind='recap') }}?from={{ d_from }}&to={{ d_to }}&emp={{ emp_id or '' }}&site={{ site|urlencode }}&sub={{ sub|urlencode }}">⬇ Export récap. heures (CSV)</a>
    <a class="g" href="{{ url_for('export', kind='site') }}?from={{ d_from }}&to={{ d_to }}&emp={{ emp_id or '' }}&site={{ site|urlencode }}&sub={{ sub|urlencode }}">⬇ Total par site (CSV)</a>
    <a class="g" href="{{ url_for('export', kind='jour') }}?from={{ d_from }}&to={{ d_to }}&emp={{ emp_id or '' }}&site={{ site|urlencode }}&sub={{ sub|urlencode }}">⬇ Export par jour (CSV)</a>
    <a class="b" style="background:#1a8f4c" href="{{ url_for('export_xlsx') }}?from={{ d_from }}&to={{ d_to }}&emp={{ emp_id or '' }}&site={{ site|urlencode }}&sub={{ sub|urlencode }}">⬇ Export Excel (.xlsx)</a>
  </form>
  <p class="mu" style="font-size:13px;margin:8px 0 0">Les exports suivent les filtres : choisissez d'abord un site (ou « Tous les sites » pour tout extraire), puis éventuellement un salarié pour n'exporter que lui, ou « Tous » pour l'ensemble des salariés. Un salarié peut pointer plusieurs fois par jour : chaque passage apparaît dans le détail, et l'export « par jour » donne le total de la journée. Chaque export contient aussi le site, l'activité, le poste, le contrat, l'horaire, les heures supplémentaires, les paniers, le quart, les tickets restau et les justificatifs d'absence.</p>
</div>
<div class="card"><h2>Total par site (heures supplémentaires)</h2><div class="sc"><table>
  <tr><th>Site</th><th>Salariés</th><th>Jours</th><th>Heures travaillées</th><th>Heures supp.</th><th>Paniers</th><th>Quart</th><th>Tickets</th><th>Abs.</th></tr>
  {% for r in site_rows %}<tr><td><b>{{ r.site }}</b></td><td>{{ r.staff }}</td><td>{{ r.days }}</td><td>{{ r.sec|dur_hm }}</td><td><b>{{ r.over|dur_hm }}</b></td><td>{{ r.panier }}</td><td>{{ r.quart }}</td><td>{{ r.ticket }}</td><td>{{ r.abs_days or '' }}</td></tr>
  {% else %}<tr><td colspan="9" class="mu">Aucune donnée.</td></tr>{% endfor %}
  {% if site_rows %}<tr style="font-weight:700"><td>TOTAL</td><td>{{ site_total.staff }}</td><td>{{ site_total.days }}</td><td>{{ site_total.sec|dur_hm }}</td><td>{{ site_total.over|dur_hm }}</td><td>{{ site_total.panier }}</td><td>{{ site_total.quart }}</td><td>{{ site_total.ticket }}</td><td>{{ site_total.abs_days or '' }}</td></tr>{% endif %}
</table></div>
<p class="mu" style="font-size:13px;margin:8px 0 0">Calculé sur la période et le filtre choisis. Aytré n'a pas de pointage ici : ses heures et heures supplémentaires restent à 0.</p></div>
<div class="card"><details><summary style="cursor:pointer;font-size:1.17em;font-weight:700">Absences par semaine ({{ abs_weeks|length }}) <span class="mu" style="font-size:13px;font-weight:400">▾ cliquer pour afficher / masquer</span></summary><div style="margin-top:10px"></div>
  {% if abs_weeks %}
  <div class="sc"><table>
    <tr><th>Semaine</th><th>Salarié</th><th>Motif</th><th>Période</th><th>Jours</th></tr>
    {% for w in week_sums %}
    <tr style="background:var(--bg2,#eef2f7);font-weight:700"><td colspan="5">{{ w.label }} <span class="mu" style="font-weight:400">({{ w.monday|day_fr }} au {{ w.sunday|day_fr }}{% if w.year != d_to[:4]|int %}, {{ w.year }}{% endif %})</span> – {{ w.days }} jour(s) d'absence, {{ w.staff }} salarié(s)</td></tr>
    {% for g in abs_weeks if g.year == w.year and g.week == w.week %}<tr><td>{{ g.label }}</td><td><a href="{{ url_for('employee_page', eid=g.eid) }}">{{ g.name }}</a>{% if g.horaire %} <span class="mu">({{ g.horaire }})</span>{% endif %}</td><td>{{ g.kind }}</td><td>{{ g.first|day_fr }}{% if g.last != g.first %} → {{ g.last|day_fr }}{% endif %}</td><td>{{ g.days }}</td></tr>{% endfor %}
    {% endfor %}
  </table></div>
  <p class="mu" style="font-size:13px;margin:8px 0 0">Absences saisies sur la période choisie, par semaine (S40, S41…) ; les jours fériés ne sont pas listés. Mêmes données dans la feuille « Absences par semaine » de l'Excel.</p>
  {% else %}<span class="mu">Aucune absence saisie sur la période.</span>{% endif %}
</details></div>
<div class="card"><details><summary style="cursor:pointer;font-size:1.17em;font-weight:700">Récapitulatif des heures ({{ totals|length }}) <span class="mu" style="font-size:13px;font-weight:400">▾ cliquer pour afficher / masquer</span></summary><div style="margin-top:10px"></div><p style="margin:0 0 10px"><input class="tsearch" type="search" placeholder="🔍 Rechercher un salarié (nom, code, poste, site…)" autocomplete="off" style="width:100%;max-width:420px;padding:10px"> <span class="tcount mu" style="font-size:13px"></span></p><div class="sc"><table>
  <tr><th>Code</th><th>Salarié</th><th>Jours</th><th>Total</th><th>Heures déc.</th><th>H. supp.</th><th>Paniers</th><th>Quart</th><th>Tickets</th><th>Abs.</th><th>Sans départ</th><th>Pauses déduites</th><th></th></tr>
  {% for o in totals %}<tr><td>{{ o.code|cd }}</td><td><a href="{{ url_for('employee_page', eid=o.eid) }}">{{ o.name }}</a></td><td>{{ o.days }}</td><td>{{ o.sec|dur_hm }}</td><td>{{ o.sec|dur_dec }}</td><td>{{ o.over|dur_hm }}</td><td>{{ o.panier }}</td><td>{{ o.quart }}</td><td>{{ o.ticket }}</td><td>{{ o.abs_days or '' }}</td><td>{{ o.open or '' }}</td><td>{{ o.pause|dur_hm if o.pause else '' }}</td><td><a href="{{ url_for('dashboard') }}?from={{ d_from }}&to={{ d_to }}&emp={{ o.eid }}">Filtrer</a></td></tr>
  {% else %}<tr><td colspan="13" class="mu">Aucun salarié.</td></tr>{% endfor %}
</table></div></details></div>
<div class="card"><details><summary style="cursor:pointer;font-size:1.17em;font-weight:700">Détail des pointages ({{ sessions|length }}) <span class="mu" style="font-size:13px;font-weight:400">▾ cliquer pour afficher / masquer</span></summary><div style="margin-top:10px"></div><p style="margin:0 0 10px"><input class="tsearch" type="search" placeholder="🔍 Rechercher un salarié (nom, code, poste, site…)" autocomplete="off" style="width:100%;max-width:420px;padding:10px"> <span class="tcount mu" style="font-size:13px"></span></p><div class="sc"><table>
  <tr><th>Code</th><th>Salarié</th><th>Date</th><th>Arrivée</th><th>Départ</th><th>Durée</th></tr>
  {% for s in sessions %}<tr><td>{{ s.code|cd }}</td><td>{{ s.name }}</td><td>{{ s.start|dfr }}</td>
    <td>{{ s.start|hm }}
      <form class="inline" method="post" action="{{ url_for('punch_delete', pid=s.in_id) }}" onsubmit="return confirm('Supprimer ce pointage d\'arrivée ?')"><input type="hidden" name="csrf_token" value="{{ csrf_token() }}"><button class="x" title="Supprimer">×</button></form></td>
    <td>{% if s.end %}{{ s.end|hm }}
      <form class="inline" method="post" action="{{ url_for('punch_delete', pid=s.out_id) }}" onsubmit="return confirm('Supprimer ce pointage de départ ?')"><input type="hidden" name="csrf_token" value="{{ csrf_token() }}"><button class="x" title="Supprimer">×</button></form>
      {% else %}<span class="err">en cours / oublié</span>{% endif %}</td>
    <td>{% if s.end %}{{ (s.end - s.start)|dur_hm }}{% endif %}</td></tr>
  {% else %}<tr><td colspan="6" class="mu">Aucune donnée.</td></tr>{% endfor %}
</table></div></details></div>
{% endblock %}"""

MACROS = r"""{% macro listfield(name, label, values, cur, newlabel) %}
<label>{{ label }}<select name="{{ name }}"><option value="">—</option>{% for v in values %}<option value="{{ v }}" {{ 'selected' if v == cur else '' }}>{{ v }}</option>{% endfor %}</select></label>
<label>{{ newlabel }}<input name="{{ name }}_new" placeholder="Créer…" maxlength="60"></label>
{% endmacro %}
{% macro fixedfield(name, label, values, cur) %}
<label>{{ label }}<select name="{{ name }}"><option value="">—</option>{% for v in values %}<option value="{{ v }}" {{ 'selected' if v == cur else '' }}>{{ v }}</option>{% endfor %}</select></label>
{% endmacro %}
{% macro emp_fields(e, opts, contrats, horaires, code_default='', site_default='', sub_default='') %}
<div class="row">
  <label>Nom complet<input name="name" value="{{ e.name if e else '' }}" required maxlength="80" placeholder="Ex. Marie Dupont"></label>
  <label>Code de pointage<input name="code" value="{{ (e.code|cd) if e else code_default }}" maxlength="30" style="text-transform:uppercase" placeholder="Facultatif pour Aytré"></label>
</div>
<div class="row" style="margin-top:10px">
  {{ listfield('site', 'Site', opts.site, e.site if e else site_default, 'ou nouveau site') }}
  {{ listfield('activite', 'Activité', opts.activite, e.activite if e else '', 'ou nouvelle activité') }}
  {{ listfield('sous_activite', 'Bâtiment', opts.sous_activite, e.sous_activite if e else sub_default, 'ou nouveau bâtiment') }}
  {{ listfield('poste', 'Poste', opts.poste, e.poste if e else '', 'ou nouveau poste') }}
</div>
<div class="row" style="margin-top:10px">
  {{ fixedfield('contrat', 'Type de contrat', contrats, e.contrat if e else '') }}
  {{ fixedfield('horaire', 'Horaire', horaires, e.horaire if e else '') }}
</div>
{% endmacro %}"""

EMPLOYEES = r"""{% extends "base.html" %}
{% block title %}GCA – Salariés{% endblock %}
{% block body %}
{% from "macros.html" import emp_fields %}
{% set active='emps' %}""" + NAV + r"""
{% if site is none %}
<div class="card"><h2>Choisissez un site</h2>
  <p class="mu" style="margin-top:0">Sélectionnez le site pour voir son personnel, ajouter un salarié ou ouvrir un dossier.</p>
  {% if error %}<p class="err">{{ error }}</p>{% endif %}
  {% if info %}<p class="okc">✓ {{ info }}</p>{% endif %}
  <div style="display:grid;grid-template-columns:repeat(auto-fit,minmax(200px,1fr));gap:12px">
    {% for s in sites %}<a href="{{ url_for('employees', site=s.name) }}" style="text-decoration:none;border:1px solid var(--bd,#ccc);border-radius:12px;padding:18px;display:block;color:inherit">
      <div style="font-size:22px;font-weight:700">{{ s.name }}</div>
      <div class="mu">{{ s.n }} salarié{{ 's' if s.n > 1 }} actif{{ 's' if s.n > 1 }}{% if s.total > s.n %} · {{ s.total - s.n }} désactivé(s){% endif %}</div></a>{% endfor %}
    {% if n_orphan %}<a href="{{ url_for('employees', site='__none__') }}" style="text-decoration:none;border:1px dashed #999;border-radius:12px;padding:18px;display:block;color:inherit">
      <div style="font-size:22px;font-weight:700">Sans site</div><div class="mu">{{ n_orphan }} salarié(s) à rattacher à un site</div></a>{% endif %}
    <a href="{{ url_for('employees', site='__all__') }}" style="text-decoration:none;border:1px solid #999;border-radius:12px;padding:18px;display:block;color:inherit">
      <div style="font-size:22px;font-weight:700">Tous les sites</div><div class="mu">{{ n_all }} salarié(s) au total</div></a>
  </div>
  <p style="margin:14px 0 0"><a class="b" style="background:#1a8f4c" href="{{ url_for('export_xlsx') }}?only=salaries">⬇ Exporter la liste des salariés (Excel)</a></p>
</div>
{% else %}
{% if need_sub %}
<p style="margin:0 0 10px"><a class="g" style="padding:8px 14px" href="{{ url_for('employees') }}">← Changer de site</a></p>
<div class="card"><h2>{{ site_label }} : choisissez un bâtiment</h2>
  <p class="mu" style="margin-top:0">Pour ce site, sélectionnez d'abord le bâtiment pour voir son personnel, ajouter un salarié ou ouvrir un dossier.</p>
  {% if error %}<p class="err">{{ error }}</p>{% endif %}
  {% if info %}<p class="okc">✓ {{ info }}</p>{% endif %}
  <div style="display:grid;grid-template-columns:repeat(auto-fit,minmax(180px,1fr));gap:12px">
    {% for s in subs %}<a href="{{ url_for('employees', site=site, sub=s.name) }}" style="text-decoration:none;border:1px solid var(--bd,#ccc);border-radius:12px;padding:16px;display:block;color:inherit">
      <div style="font-size:19px;font-weight:700">{{ s.name }}</div>
      <div class="mu">{{ s.n }} salarié{{ 's' if s.n > 1 }} actif{{ 's' if s.n > 1 }}{% if s.total > s.n %} · {{ s.total - s.n }} désactivé(s){% endif %}</div></a>{% endfor %}
    {% if n_nosub %}<a href="{{ url_for('employees', site=site, sub='__none__') }}" style="text-decoration:none;border:1px dashed #999;border-radius:12px;padding:16px;display:block;color:inherit">
      <div style="font-size:19px;font-weight:700">Sans bâtiment</div><div class="mu">{{ n_nosub }} salarié(s) à rattacher</div></a>{% endif %}
    <a href="{{ url_for('employees', site=site, sub='__all__') }}" style="text-decoration:none;border:1px solid #999;border-radius:12px;padding:16px;display:block;color:inherit">
      <div style="font-size:19px;font-weight:700">Tous les bâtiments</div><div class="mu">Tout le personnel de {{ site_label }}</div></a>
  </div>
</div>
{% else %}
<p style="margin:0 0 10px"><a class="g" style="padding:8px 14px" href="{{ url_for('employees') }}">← Changer de site</a>{% if sub %} <a class="g" style="padding:8px 14px" href="{{ url_for('employees', site=site) }}">← Changer de bâtiment</a>{% endif %}</p>
<div class="card"><h2>Ajouter un salarié{% if site not in ('__all__','__none__') %} – {{ site_label }}{% endif %}</h2>
  <form method="post" action="{{ url_for('employee_add') }}">
    <input type="hidden" name="csrf_token" value="{{ csrf_token() }}">
    <input type="hidden" name="back_site" value="{{ site }}"><input type="hidden" name="back_sub" value="{{ sub or '' }}">
    {{ emp_fields(none, opts, contrats, horaires, suggested, site_label if site not in ('__all__','__none__') else '', sub_label if sub and sub not in ('__all__','__none__') else '') }}
    <p class="mu" style="font-size:13px;margin:10px 0">Panier, quart et tickets restau se calculent automatiquement selon l'horaire : Matin, Après-midi et Nuit = panier 1, quart 1, tickets 0 ; Journée = panier 0, quart 0, tickets 1.</p>
    <button class="b" type="submit">Ajouter</button>
  </form>
  {% if error %}<p class="err">{{ error }}</p>{% endif %}
  {% if info %}<p class="okc">✓ {{ info }}</p>{% endif %}
</div>
<div class="card"><h2>Salariés – {{ site_label }}{% if sub_label %} – {{ sub_label }}{% endif %} ({{ emps|length }})</h2><p style="margin:0 0 10px"><input class="tsearch" type="search" placeholder="🔍 Rechercher un salarié (nom, code, poste…)" autocomplete="off" style="width:100%;max-width:420px;padding:10px"> <span class="tcount mu" style="font-size:13px"></span></p><p style="margin:0 0 10px"><a class="b" style="background:#1a8f4c" href="{{ url_for('export_xlsx') }}?only=salaries&site={{ site|urlencode }}&sub={{ (sub or '')|urlencode }}">⬇ Exporter la liste des salariés{% if site not in ('__all__',) %} – {{ site_label }}{% endif %} (Excel)</a></p><div class="sc"><table class="wrap">
  <tr><th>Code</th><th>Nom</th><th>Site</th><th>Activité</th><th>Bâtiment</th><th>Poste</th><th>Contrat</th><th>Horaire</th><th>Panier / Quart / Tickets</th><th>Statut</th><th></th></tr>
  {% for e in emps %}{% set b = shift_bonus(e.horaire) %}<tr>
    <td><b>{{ e.code|cd }}</b></td>
    <td><a href="{{ url_for('employee_page', eid=e.id) }}">{{ e.name }}</a></td>
    <td>{{ e.site }}</td><td>{{ e.activite }}</td><td>{{ e.sous_activite }}</td><td>{{ e.poste }}</td><td>{{ e.contrat }}</td><td>{{ e.horaire }}</td>
    <td>{% if b %}{{ b[0] }} / {{ b[1] }} / {{ b[2] }}{% else %}<span class="mu">—</span>{% endif %}</td>
    <td>{% if e.active %}<span class="okc">Actif</span>{% else %}<span class="mu">Désactivé</span>{% endif %}</td>
    <td style="text-align:right;white-space:nowrap;min-width:190px"><a class="g" style="padding:5px 10px" href="{{ url_for('employee_page', eid=e.id) }}">Dossier</a>
      <a class="g" style="padding:5px 10px" href="{{ url_for('employee_page', eid=e.id, _anchor='transfert') }}">Transférer</a>
      <a class="g" style="padding:5px 10px;color:var(--ko)" href="{{ url_for('employee_page', eid=e.id, _anchor='supprimer') }}">Supprimer</a>
      <form method="post" action="{{ url_for('employee_toggle', eid=e.id) }}" class="inline">
        <input type="hidden" name="csrf_token" value="{{ csrf_token() }}"><input type="hidden" name="back_site" value="{{ site }}"><input type="hidden" name="back_sub" value="{{ sub or '' }}">
        <button class="g" type="submit" style="padding:5px 10px">{{ 'Désactiver' if e.active else 'Réactiver' }}</button></form></td>
  </tr>{% else %}<tr><td colspan="11" class="mu">Aucun salarié.</td></tr>{% endfor %}
</table></div>
<p class="mu" style="font-size:13px;margin:8px 0 0">Cliquez sur un nom pour ouvrir son dossier. Un salarié désactivé ne peut plus pointer, mais son historique est conservé.</p></div>
{% endif %}{% endif %}
{% if site is none %}
<div class="card" id="listes"><h2>Listes déroulantes</h2>
  <p class="mu" style="margin-top:0">Ajoutez ici une activité, un site ou un poste : il apparaît aussitôt dans les listes des dossiers. Vous pouvez aussi en créer un directement dans le dossier d'un salarié. Le chiffre entre parenthèses indique combien de salariés l'utilisent.</p>
  {% for k, label in kinds %}
  <div style="margin-bottom:14px"><b>{{ label }}</b>
    <div>{% for o in managed[k] %}<span class="chip">{{ o.value }}{% if o.used %} <span class="mu">({{ o.used }})</span>{% endif %}
      <form class="inline" method="post" action="{{ url_for('option_delete', oid=o.id) }}"><input type="hidden" name="csrf_token" value="{{ csrf_token() }}"><button class="x" title="Retirer de la liste">×</button></form></span>{% else %}<span class="mu">Liste vide.</span>{% endfor %}</div>
    <form method="post" action="{{ url_for('option_add') }}" class="row" style="margin-top:6px">
      <input type="hidden" name="csrf_token" value="{{ csrf_token() }}"><input type="hidden" name="kind" value="{{ k }}">
      <label>Nouvelle valeur<input name="value" required maxlength="60"></label>
      <button class="g" type="submit">Ajouter à « {{ label }} »</button></form>
  </div>{% endfor %}
</div>
<div class="card" style="border-color:var(--ko)"><h2>Remise à zéro</h2>
  <p class="mu" style="margin-top:0">Action <b>définitive</b> : pensez à télécharger vos exports avant.</p>
  <form method="post" action="{{ url_for('reset_data') }}" class="row">
    <input type="hidden" name="csrf_token" value="{{ csrf_token() }}">
    <label>Effacer<select name="scope"><option value="punches">Tous les pointages et absences (garder les salariés)</option><option value="all">Tout : salariés, pointages et absences</option></select></label>
    <label>Tapez EFFACER pour confirmer<input name="confirm" autocomplete="off" required></label>
    <button class="b" type="submit" style="background:var(--ko)">Effacer définitivement</button>
  </form></div>
{% endif %}
{% endblock %}"""

EMPLOYEE = r"""{% extends "base.html" %}
{% block title %}GCA – {{ e.name }}{% endblock %}
{% block body %}
{% from "macros.html" import emp_fields %}
{% set active='emps' %}""" + NAV + r"""
<p style="margin:0 0 10px"><a href="{{ url_for('employees') }}">← Tous les salariés</a></p>
<div class="card"><h2>Dossier : {{ e.name }} <span class="mu">{{ e.code|cdp }}</span>{% if not e.active %} <span class="err">désactivé</span>{% endif %}</h2>
  {% if error %}<p class="err">{{ error }}</p>{% endif %}
  {% if info %}<p class="okc">✓ {{ info }}</p>{% endif %}
  <form method="post" action="{{ url_for('employee_update', eid=e.id) }}">
    <input type="hidden" name="csrf_token" value="{{ csrf_token() }}">
    {{ emp_fields(e, opts, contrats, horaires) }}
    <button class="b" type="submit" style="margin-top:12px">Enregistrer le dossier</button>
  </form>
</div>
{% set b = shift_bonus(e.horaire) %}
<div class="card" id="transfert"><h2>Transférer vers une autre activité ou un autre site</h2>
  <p class="mu" style="margin-top:0">Situation actuelle : <b>{{ e.activite or '—' }}</b>{% if e.sous_activite %} ({{ e.sous_activite }}){% endif %} · {{ e.site or '—' }} · {{ e.poste or '—' }} · {{ e.horaire or '—' }}.
  Choisissez la nouvelle affectation : le salarié change aussitôt de liste. {% if e.code|cd %}Son <b>code de pointage ({{ e.code }}) ne change pas</b>{% else %}Il n'a pas de code de pointage{% endif %}, ni son historique. Laissez « Inchangé » pour ce qui ne bouge pas.</p>
  <form method="post" action="{{ url_for('employee_transfer', eid=e.id) }}">
    <input type="hidden" name="csrf_token" value="{{ csrf_token() }}">
    <div class="row">
      <label>Nouvelle activité<select name="activite"><option value="">Inchangé</option>{% for v in opts.activite if v != e.activite %}<option value="{{ v }}">{{ v }}</option>{% endfor %}</select></label>
      <label>ou nouvelle activité<input name="activite_new" placeholder="Créer…" maxlength="60"></label>
      <label>Nouveau bâtiment<select name="sous_activite"><option value="">Inchangé</option>{% for v in opts.sous_activite if v != e.sous_activite %}<option value="{{ v }}">{{ v }}</option>{% endfor %}</select></label>
      <label>ou nouveau bâtiment<input name="sous_activite_new" placeholder="Créer…" maxlength="60"></label>
      <label>Nouveau site<select name="site"><option value="">Inchangé</option>{% for v in opts.site if v != e.site %}<option value="{{ v }}">{{ v }}</option>{% endfor %}</select></label>
      <label>ou nouveau site<input name="site_new" placeholder="Créer…" maxlength="60"></label>
    </div>
    <div class="row" style="margin-top:10px">
      <label>Nouveau poste<select name="poste"><option value="">Inchangé</option>{% for v in opts.poste if v != e.poste %}<option value="{{ v }}">{{ v }}</option>{% endfor %}</select></label>
      <label>Nouvel horaire<select name="horaire"><option value="">Inchangé</option>{% for v in horaires if v != e.horaire %}<option value="{{ v }}">{{ v }}</option>{% endfor %}</select></label>
      <label>Horaire à partir du<input type="date" name="horaire_from" value="{{ today }}"></label>
    </div>
    <p class="mu" style="font-size:13px;margin:10px 0">Le changement d'horaire s'applique <b>à partir de la date choisie</b> : les jours précédents gardent l'ancien horaire (et leurs droits). Pour les autres champs (activité, site, poste), les exports des périodes passées utilisent l'affectation actuelle. Téléchargez vos exports du mois en cours avant un transfert si vous voulez garder l'ancienne activité.</p>
    <button class="b" type="submit">Transférer</button>
  </form>
  {% if moves %}<div class="sc" style="margin-top:12px"><table><tr><th>Date</th><th>Changements</th></tr>
  {% for m in moves %}<tr><td>{{ m.day.strftime('%d/%m/%Y %H:%M') }}</td><td>{{ m.changes }}</td></tr>{% endfor %}</table></div>{% endif %}
</div>
<div class="card"><h2>Calculs automatiques</h2>
  <div class="row" style="align-items:stretch">
    <div class="stat"><b>{{ THEORETICAL_SEC|dur_hm }}</b><span>Heure théorique / jour travaillé</span></div>
    <div class="stat"><b>{{ b[0] if b else '—' }}</b><span>Panier / jour</span></div>
    <div class="stat"><b>{{ b[1] if b else '—' }}</b><span>Quart / jour</span></div>
    <div class="stat"><b>{{ b[2] if b else '—' }}</b><span>Tickets restau / jour</span></div>
  </div>
  <p class="mu" style="font-size:13px;margin:10px 0 0">Heures supplémentaires = heures pointées dans la journée − {{ THEORETICAL_SEC|dur_hm }} (si positif). Exemple : 7h50 pointées = 50 min supplémentaires.
  {% if b %}Valeurs liées à l'horaire « {{ e.horaire }} ».{% else %}<b>Choisissez un horaire</b> pour activer le calcul des paniers, du quart et des tickets restau.{% endif %}</p>
</div>
<div class="card"><h2>Suivi sur une période</h2>
  <form method="get" class="row">
    <label>Du<input type="date" name="from" value="{{ d_from }}"></label>
    <label>Au<input type="date" name="to" value="{{ d_to }}"></label>
    <button class="b" type="submit">Afficher</button>
    <a class="g" href="{{ url_for('export', kind='detail') }}?from={{ d_from }}&to={{ d_to }}&emp={{ e.id }}">⬇ Export détail</a>
    <a class="g" href="{{ url_for('export', kind='jour') }}?from={{ d_from }}&to={{ d_to }}&emp={{ e.id }}">⬇ Export par jour</a>
    <a class="g" href="{{ url_for('export', kind='recap') }}?from={{ d_from }}&to={{ d_to }}&emp={{ e.id }}">⬇ Export récap.</a>
    <a class="b" style="background:#1a8f4c" href="{{ url_for('export_xlsx') }}?from={{ d_from }}&to={{ d_to }}&emp={{ e.id }}">⬇ Export Excel (.xlsx)</a>
  </form>
  <div class="row" style="margin-top:12px;align-items:stretch">
    <div class="stat"><b>{{ tot.days }}</b><span>Jours travaillés</span></div>
    <div class="stat"><b>{{ tot.sec|dur_hm }}</b><span>Heures travaillées</span></div>
    <div class="stat"><b>{{ THEORETICAL_SEC|dur_hm }}</b><span>Heure théorique / jour</span></div>
    <div class="stat"><b>{{ tot.over|dur_hm }}</b><span>Heures supplémentaires</span></div>
    <div class="stat"><b>{{ tot.panier }}</b><span>Paniers</span></div>
    <div class="stat"><b>{{ tot.quart }}</b><span>Quart</span></div>
    <div class="stat"><b>{{ tot.ticket }}</b><span>Tickets restau</span></div>
    <div class="stat"><b>{{ tot.abs_days }}</b><span>Jours d'absence</span></div>
  </div>
</div>
<div class="card"><h2>Détail par jour</h2><div class="sc"><table>
  <tr><th>Date</th><th>Passages</th><th>Arrivée</th><th>Départ</th><th>Travaillé</th><th>Théorique</th><th>H. supp.</th><th>Panier</th><th>Quart</th><th>Tickets</th><th>Justificatif d'absence</th></tr>
  {% for r in rows %}<tr>
    <td>{{ r.day|day_fr }}</td><td>{{ r.n or ('saisi' if r.manual else '') }}</td>
    <td>{{ r.first|hm if r.first else '' }}</td>
    <td>{% if r.last %}{{ r.last|hm }}{% endif %}{% if r.open %} <span class="err">sans départ</span>{% endif %}</td>
    <td>{{ r.sec|dur_hm if r.worked else '' }}</td><td>{{ r.theo|dur_hm if r.worked else '' }}</td>
    <td>{{ r.over|dur_hm if r.worked else '' }}</td>
    <td>{{ '' if r.panier is none else r.panier }}</td><td>{{ '' if r.quart is none else r.quart }}</td><td>{{ '' if r.ticket is none else r.ticket }}</td>
    <td>{{ r.absence }}</td></tr>
  {% else %}<tr><td colspan="11" class="mu">Aucune donnée sur la période.</td></tr>{% endfor %}
</table></div></div>
<div class="card" id="presences"><h2>Présence (site sans pointage)</h2>
  <p class="mu" style="margin-top:0"><b>Pour les sites dont le pointage se fait ailleurs (ex. Aytré), le salarié est considéré présent du lundi au vendredi avec son horaire « {{ e.horaire or '—' }} », sauf jour d'absence saisi.</b> Les paniers, le quart et les tickets restau en découlent, sans heures pointées. Utilisez le formulaire ci-dessous seulement pour un jour <b>différent</b> : samedi ou dimanche travaillé, ou autre horaire sur une période. Les absences se saisissent dans la carte suivante.</p>
  <form method="post" action="{{ url_for('employee_since', eid=e.id) }}" class="row" style="margin-bottom:10px">
    <input type="hidden" name="csrf_token" value="{{ csrf_token() }}">
    <label>Présent par défaut à partir du<input type="date" name="since" value="{{ e.since }}" required></label>
    <button class="g" type="submit">Enregistrer la date</button>
  </form>
  <form method="post" action="{{ url_for('presence_add', eid=e.id) }}" class="row">
    <input type="hidden" name="csrf_token" value="{{ csrf_token() }}">
    <label>Horaire<select name="horaire" required>{% for h in horaires %}<option value="{{ h }}" {{ 'selected' if h == e.horaire }}>{{ h }}</option>{% endfor %}</select></label>
    <label>Du<input type="date" name="from" value="{{ today }}" required></label>
    <label>Au<input type="date" name="to" value="{{ today }}" required></label>
    <label style="flex-direction:row;align-items:center;gap:6px;color:var(--tx);font-size:14px"><input type="checkbox" name="weekdays" value="1" checked> Ignorer samedi et dimanche (si plusieurs jours)</label>
    <button class="b" type="submit">Enregistrer</button>
  </form>
  <div class="sc" style="margin-top:12px"><table><tr><th>Date</th><th>Horaire (jour différent)</th><th></th></tr>
  {% for p in presences %}<tr><td>{{ p.day|day_fr }}</td><td>{{ p.horaire }}</td><td style="text-align:right">
    <form class="inline" method="post" action="{{ url_for('presence_delete', pid=p.id) }}"><input type="hidden" name="csrf_token" value="{{ csrf_token() }}"><button class="x">Supprimer</button></form></td></tr>
  {% else %}<tr><td colspan="3" class="mu">Aucun jour particulier saisi.</td></tr>{% endfor %}</table></div>
</div>
<div class="card" id="supprimer" style="border-color:var(--ko)"><h2>Supprimer ce salarié</h2>
  <p class="mu" style="margin-top:0">Suppression <b>définitive</b> de {{ e.name }}{{ e.code|cdp }} et de toutes ses données : pointages, absences, jours saisis et historique. Elle disparaît aussi de toutes les extractions, y compris des mois passés. <b>Téléchargez d'abord vos exports.</b> Pour simplement arrêter les pointages en gardant l'historique, utilisez plutôt « Désactiver » dans la liste des salariés.</p>
  <form method="post" action="{{ url_for('employee_delete', eid=e.id) }}" class="row">
    <input type="hidden" name="csrf_token" value="{{ csrf_token() }}">
    <label>Pour confirmer, tapez : <b>{{ (e.code|cd) or 'SUPPRIMER' }}</b><input name="confirm" required autocomplete="off" style="text-transform:uppercase"></label>
    <button class="b" type="submit" style="background:var(--ko)">Supprimer définitivement</button>
  </form>
</div>
<div class="card" id="absences"><h2>Justificatif d'absence</h2>
  <form method="post" action="{{ url_for('absence_add', eid=e.id) }}" enctype="multipart/form-data" class="row">
    <input type="hidden" name="csrf_token" value="{{ csrf_token() }}">
    <label>Justificatif<select name="kind" required>{% for k in absence_kinds %}<option value="{{ k }}">{{ k }}</option>{% endfor %}</select></label>
    <label>Du<input type="date" name="from" value="{{ today }}" required></label>
    <label>Au<input type="date" name="to" value="{{ today }}" required></label>
    <label>Document (facultatif – PDF, JPG ou PNG, {{ max_mb }} Mo max)<input type="file" name="file" accept=".pdf,.jpg,.jpeg,.png,application/pdf,image/jpeg,image/png"></label>
    <label style="flex-direction:row;align-items:center;gap:6px;color:var(--tx);font-size:14px"><input type="checkbox" name="weekdays" value="1" checked> Ignorer samedi et dimanche (si plusieurs jours)</label>
    <button class="b" type="submit">Enregistrer</button>
  </form>
  <div class="sc" style="margin-top:12px"><table><tr><th>Date</th><th>Justificatif</th><th>Document</th><th></th></tr>
  {% for a in absences %}<tr><td>{{ a.day|day_fr }}</td><td>{{ a.kind }}</td>
    <td>{% for d in a.docs %}<div style="margin:2px 0"><span>📎 {{ d.filename }}</span>
      <a href="{{ url_for('doc_view', did=d.id) }}" target="_blank" rel="noopener">Consulter</a> ·
      <a href="{{ url_for('doc_view', did=d.id) }}?dl=1">Télécharger</a>
      <form class="inline" method="post" action="{{ url_for('doc_delete', did=d.id) }}" onsubmit="return confirm('Supprimer ce document{% if d.day_to != d.day_from %} (valable du {{ d.day_from|day_fr }} au {{ d.day_to|day_fr }}, il sera retiré de toute la période){% endif %} ?')"><input type="hidden" name="csrf_token" value="{{ csrf_token() }}"><button class="x" title="Supprimer le document">×</button></form>
      {% if d.day_to != d.day_from %}<span class="mu" style="font-size:12px">(du {{ d.day_from|day_fr }} au {{ d.day_to|day_fr }})</span>{% endif %}</div>{% endfor %}
      <form method="post" action="{{ url_for('absence_doc_add', aid=a.id) }}" enctype="multipart/form-data" class="inline" style="margin-top:4px"><input type="hidden" name="csrf_token" value="{{ csrf_token() }}"><input type="file" name="file" accept=".pdf,.jpg,.jpeg,.png,application/pdf,image/jpeg,image/png" required style="max-width:190px;font-size:12px"> <button class="x">{{ 'Ajouter un autre' if a.docs else 'Ajouter un document' }}</button></form></td>
    <td style="text-align:right"><form class="inline" method="post" action="{{ url_for('absence_delete', aid=a.id) }}"><input type="hidden" name="csrf_token" value="{{ csrf_token() }}"><button class="x">Supprimer</button></form></td></tr>
  {% else %}<tr><td colspan="4" class="mu">Aucune absence enregistrée.</td></tr>{% endfor %}</table></div>
  <p class="mu" style="font-size:13px;margin:8px 0 0">Le document est facultatif : on peut l'ajouter à la saisie ou plus tard, pour chaque absence. Visible uniquement par le gérant connecté. L'export Excel / CSV « Par jour » indique « Oui / Non » dans « Document joint ». Les documents sont supprimés avec l'absence ou le salarié.</p>
</div>
{% endblock %}"""

